-- Generated by ekos-lakehouse (RFC 0195): `films` in gold__film_catalog_by_rating reconciles to silver.
with mart as (
    select sum("films") as v from {{ ref('gold__film_catalog_by_rating') }}
),

silver as (
    select count("film"."film_id") as v
    from {{ ref('public__film') }} as "film"
)

select mart.v as mart_total, silver.v as silver_total
from mart, silver
where mart.v is distinct from silver.v
